import unittest
from candidate import has_close_elements


class TestHasCloseElements(unittest.TestCase):
    def test_has_close_elements_normal_case_returns_true(self):
        self.assertTrue(has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3))

    def test_has_close_elements_normal_case_returns_false(self):
        self.assertFalse(has_close_elements([1.0, 2.0, 3.0], 0.5))

    def test_has_close_elements_boundary_threshold_equal_distance_returns_false(self):
        self.assertFalse(has_close_elements([1.0, 2.0], 1.0))

    def test_has_close_elements_empty_input_list_returns_false(self):
        self.assertFalse(has_close_elements([], 0.5))

    def test_has_close_elements_single_element_list_returns_false(self):
        self.assertFalse(has_close_elements([5.0], 0.5))

    def test_has_close_elements_duplicate_values_within_threshold_returns_true(self):
        self.assertTrue(has_close_elements([1.0, 1.0], 0.1))

    def test_has_close_elements_none_for_numbers_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements(None, 0.5)

    def test_has_close_elements_none_for_threshold_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements([1.0, 2.0], None)

    def test_has_close_elements_negative_threshold_returns_false(self):
        self.assertFalse(has_close_elements([1.0, 2.0], -0.1))

    def test_has_close_elements_large_threshold_covering_all_pairs_returns_true(self):
        self.assertTrue(has_close_elements([1.0, 10.0], 100.0))

    def test_has_close_elements_unsorted_list_returns_true(self):
        self.assertTrue(has_close_elements([5.0, 1.0, 3.0], 2.1))

    def test_has_close_elements_returns_false_when_no_pairs_below_threshold(self):
        self.assertFalse(has_close_elements([0.0, 10.0, 20.0], 5.0))

    def test_has_close_elements_threshold_zero_returns_false(self):
        self.assertFalse(has_close_elements([1.0, 2.0], 0.0))
